using UnityEngine;

namespace TrainSurvivor.Game.View
{
    /// <summary>
    /// Marks a prefab as an enemy model cut from art-work/enemies: the id the sim uses,
    /// the sprite it draws and the world height it should stand at. Prefabs live in
    /// Assets/_Project/Prefabs/Enemies and are generated by tools + the editor builder;
    /// tweak the prefab freely, but the id must match data/enemies.json.
    /// </summary>
    public sealed class EnemyModel : MonoBehaviour
    {
        [Tooltip("Roster id from finalized-for-develop/data/enemies.json")]
        public string enemyId = "walker";

        [Tooltip("Sprite name inside atlas_enemies (en_<id>)")]
        public string spriteName = "en_walker";

        [Tooltip("World height in metres — the billboard scales from this")]
        public float heightM = 2f;

        [Tooltip("Optional source card, for the codex / design review")]
        public Texture2D card;
    }
}
